          }}
        />
        <ProFormSelect
          name="temp_threshold_id"
          label="温度阀值"
          request={async () => {
            const thresholds = await listSensorThresholds();
            return (thresholds || [])
              .filter((item) => item.metric === 2)
              .map((item) => ({
                value: item.id,
                label: `${item.code} - 温度阀值`,
              }));
          }}
        />
        <ProForm.Item name="parent_id" label="上级分类">
          <EntityPicker<DeviceCategory>
            placeholder="可选，点击选择上级分类"
            modalTitle="选择上级分类"
            triggerText="选择"
            valueLabel={
              editing?.parent_id
                ? categoryMap.get(editing.parent_id)?.name
                : createChildParent
                  ? createChildParent.name
                  : undefined
            }
            columns={parentPickerColumns}
            treeData={pickerTreeData}
            treeColumns={[
              { title: '分类名称', dataIndex: 'name' },
              { title: '描述', dataIndex: 'description', render: (_, row) => row.description || '-' },
            ]}
            getRecordLabel={(record) => record.name}
            fetcher={async ({ current, pageSize, keyword }) => {
              const result = await queryDeviceCategories({ current, pageSize, keyword });
              if (blockedParentIds.size === 0) {
                return result;
              }
              return {
                ...result,
                items: result.items.filter((item) => !blockedParentIds.has(item.id)),
              };
            }}
          />
        </ProForm.Item>
      </ModalForm>

      {/* 负责员工配置弹窗 */}
      <Modal
        title={`设置负责员工 - ${currentCategory?.name}`}
        open={transferModalOpen}
        onCancel={() => {
          setTransferModalOpen(false);
          setCurrentCategory(null);
          setTargetKeys([]);
        }}
        onOk={async () => {
          if (!currentCategory) return;
          setSaving(true);
          try {
            await updateDeviceCategoryEmployees(currentCategory.id, targetKeys as string[]);
            message.success('负责员工设置成功');
            setTransferModalOpen(false);
            setCurrentCategory(null);
            setTargetKeys([]);
            await loadCategories();
          } catch (error) {
            message.error(toErrorMessage(error));
          } finally {
            setSaving(false);
          }
        }}
        confirmLoading={saving}
        width={700}
        destroyOnClose
      >
        <Transfer
          dataSource={employees.map(emp => ({
            key: emp.id,
            title: `${emp.name} (${emp.mobile || '无手机号'})`,
            description: emp.name,
          }))}
          showSearch
          listStyle={{
            width: 300,
